{
  "tables": ["match", "team", "team_attributes"],
  "columns": ["team_attributes.buildupplayspeedclass"],
  "filters": [
    {"table": "match", "column": "season", "op": "=", "value": "2012/2013"},
    {"table": "match", "column": "home_team_api_id", "op": "=", "value": "10135"},
    {"table": "match", "column": "away_team_api_id", "op": "=", "value": "10135"},
    {"table": "match", "column": "id", "op": "IN", "value": "(SELECT MAX(id) FROM match WHERE home_team_api_id = 10135 OR away_team_api_id = 10135)"},
    {"table": "team_attributes", "column": "team_api_id", "op": "=", "value": "10135"},
    {"table": "team_attributes", "column": "date", "op": "<=", "value": "(SELECT MAX(date) FROM match WHERE home_team_api_id = 10135 OR away_team_api_id = 10135)"}
  ]
}

