{
  "tables": [
    "account",
    "trans",
    "district"
  ],
  "columns": [
    "district.a2",
    "district.a3",
    "district.a8",
    "sum(trans.amount)",
    "round(sum(trans.amount) / district.a8, 2)",
    "rank() over (order by round(sum(trans.amount) / district.a8, 2) desc)",
    "avg(case when loan.type = 'debit' then loan.amount else 0 end)"
  ],
  "filters": [
    {
      "table": "trans",
      "column": "type",
      "op": "=",
      "value": "withdrawal"
    },
    {
      "table": "district",
      "column": "a8",
      "op": ">=",
      "value": 100000
    }
  ]
}

{
  "tables": ["account", "loan", "district"],
  "columns": [
    "account.account_id",
    "account.date",
    "loan.amount",
    "district.district_id"
  ],
  "filters": [
    {
      "table": "account",
      "column": "date",
      "op": ">=",
      "value": "1996-01-01"
    },
    {
      "table": "account",
      "column": "district_id",
      "op": "IN",
      "value": "(SELECT district_id FROM district WHERE a2 = 'central Bohemia')"
    }
  ]
}

{
  "tables": ["schools", "satscores"],
  "columns": ["schools.school", "schools.admemail1", "satscores.numge1500"],
  "filters": [
    {"table": "schools", "column": "statustype", "op": "=", "value": "Directly Run by State Board of Education"},
    {"table": "schools", "column": "charter", "op": "=", "value": 1}
  ]
}

{
  "tables": ["frpm", "schools", "satscores"],
  "columns": [
    "frpm.cdscode",
    "frpm.Academic Year",
    "schools.cdscode",
    "schools.county",
    "schools.opendate",
    "satscores.cds",
    "satscores.numtsttakr"
  ],
  "filters": [
    {
      "table": "schools",
      "column": "county",
      "op": "=",
      "value": "Los Angeles"
    },
    {
      "table": "schools",
      "column": "opendate",
      "op": ">=",
      "value": "2007-01-01"
    },
    {
      "table": "schools",
      "column": "opendate",
      "op": "<",
      "value": "2008-01-01"
    },
    {
      "table": "schools",
      "column": "statustype",
      "op": "=",
      "value": "district"
    },
    {
      "table": "satscores",
      "column": "cds",
      "op": "IN",
      "value": "(SELECT cdscode FROM schools WHERE county = 'Los Angeles' AND opendate >= '2007-01-01' AND opendate < '2008-01-01' AND statustype = 'district')"
    }
  ]
}

{
